1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  /** Zero-based index of the quote step that created the policy. */
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export type Step = QuoteStep | ClaimStep;
31	
32	export interface Customer {
33	  yearsWithMHPCO: number;
34	}
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export interface ScenarioResults {
51	  results: (QuoteResult | ClaimResult)[];
52	}
53	
54	const PROCESSING_FEE = 5;
55	const FIRST_INSURANCE_SURCHARGE = 0.1;
56	const CURSE_SURCHARGE = 0.5;
57	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const LOYALTY_DISCOUNT = 0.2;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
62	
63	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
64	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
65	
66	interface ItemTariff {
67	  basePremium: number;
68	  insuranceValue: number;
69	}
70	
71	/** The known item types, with the two rates the tariff sets for each. */
72	const TARIFF: Record<string, ItemTariff> = {
73	  sword: { basePremium: 100, insuranceValue: 1000 },
74	  amulet: { basePremium: 60, insuranceValue: 600 },
75	  staff: { basePremium: 80, insuranceValue: 800 },
76	  potion: { basePremium: 40, insuranceValue: 400 },
77	  rune: { basePremium: 25, insuranceValue: 250 },
78	  moonstone: { basePremium: 25, insuranceValue: 250 },
79	};
80	
81	const DEDUCTIBLE = 100;
82	const CAP_MULTIPLIER = 2;
83	const STRONG_ENCHANTMENT_THRESHOLD = 8;
84	const STRONG_ENCHANTMENT_REIMBURSEMENT = 0.5;
85	
86	const COMPONENT_TYPES = ["rune", "moonstone"];
87	const BLOCK_SIZE = 3;
88	const BLOCK_BASE_PREMIUM = 60;
89	
90	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
91	
92	const countByType = (items: Item[]): Map<string, number> => {
93	  const counts = new Map<string, number>();
94	
95	  for (const item of items) {
96	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	  }
98	
99	  return counts;
100	};
101	
102	/** Exactly BLOCK_SIZE alike components form a building block. */
103	const formsBuildingBlock = (type: string, count: number): boolean =>
104	  isComponent(type) && count === BLOCK_SIZE;
105	
106	const tariffFor = (type: string): ItemTariff => {
107	  const tariff = TARIFF[type];
108	
109	  if (tariff === undefined) {
110	    throw new Error(`unknown item type: ${type}`);
111	  }
112	
113	  return tariff;
114	};
115	
116	const itemBasePremium = (type: string): number => tariffFor(type).basePremium;
117	
118	const itemInsuranceValue = (type: string): number => tariffFor(type).insuranceValue;
119	
120	/** Alike items are priced together so a building block can be recognised. */
121	const groupBasePremium = (type: string, count: number): number =>
122	  formsBuildingBlock(type, count)
123	    ? BLOCK_BASE_PREMIUM
124	    : count * itemBasePremium(type);
125	
126	/** The policy base premium is the sum of the base premiums of its items. */
127	const policyBasePremium = (items: Item[]): number =>
128	  [...countByType(items)].reduce(
129	    (total, [type, count]) => total + groupBasePremium(type, count),
130	    0,
131	  );
132	
133	const isCursed = (item: Item): boolean => item.cursed === true;
134	
135	const isHighlyEnchanted = (item: Item): boolean =>
136	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
137	
138	/**
139	 * Item-specific surcharges stack additively, as fractions of the item's base
140	 * premium.
141	 */
142	const itemSurchargeRate = (item: Item): number =>
143	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
144	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
145	
146	/**
147	 * Item-specific modifiers apply to the base premium of the affected item,
148	 * not to the policy total.
149	 */
150	const itemSurcharges = (items: Item[]): number =>
151	  items.reduce(
152	    (total, item) =>
153	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
154	    0,
155	  );
156	
157	const isLoyalCustomer = (customer: Customer): boolean =>
158	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
159	
160	/**
161	 * Policy-wide modifiers, as fractions of the policy base premium. Each is an
162	 * amount added to (or, when negative, subtracted from) that base premium, so
163	 * modifiers stack additively rather than compounding.
164	 */
165	const policyModifierRates = (
166	  customer: Customer,
167	  isFollowUpContract: boolean,
168	): number[] => [
169	  FIRST_INSURANCE_SURCHARGE,
170	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
171	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
172	];
173	
174	const policyModifiers = (
175	  basePremium: number,
176	  customer: Customer,
177	  isFollowUpContract: boolean,
178	): number =>
179	  policyModifierRates(customer, isFollowUpContract).reduce(
180	    (total, rate) => total + basePremium * rate,
181	    0,
182	  );
183	
184	const quotePremium = (
185	  step: QuoteStep,
186	  customer: Customer,
187	  isFollowUpContract: boolean,
188	): number => {
189	  const basePremium = policyBasePremium(step.items);
190	
191	  return roundUp(
192	    basePremium +
193	      itemSurcharges(step.items) +
194	      policyModifiers(basePremium, customer, isFollowUpContract) +
195	      PROCESSING_FEE,
196	  );
197	};
198	
199	/**
200	 * Every contract after the customer's first is a follow-up. Only quote steps
201	 * create contracts, so this counts preceding quotes rather than preceding steps.
202	 */
203	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
204	  precedingSteps.some((step) => step.op === "quote");
205	
206	/** Payouts are rounded down (in the MHPCO's favour), ignoring float noise. */
207	const roundDown = (amount: number): number =>
208	  Math.floor(Number(amount.toFixed(6)));
209	
210	/** The insurance sum is the sum of the items' insurance values. */
211	const insuranceSum = (items: Item[]): number =>
212	  items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
213	
214	const isStronglyEnchanted = (item: Item): boolean =>
215	  (item.enchantment ?? 0) >= STRONG_ENCHANTMENT_THRESHOLD;
216	
217	/**
218	 * The reimbursement clauses decide how much of the damage is reimbursed,
219	 * before the deductible is applied.
220	 */
221	const reimbursementRate = (item: Item): number =>
222	  isStronglyEnchanted(item) ? STRONG_ENCHANTMENT_REIMBURSEMENT : 1;
223	
224	const damagePayout = (damage: Damage, item: Item): number =>
225	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
226	
227	/** A policy pays out at most CAP_MULTIPLIER times its insurance sum. */
228	const policyCap = (policy: QuoteStep): number =>
229	  insuranceSum(policy.items) * CAP_MULTIPLIER;
230	
231	/** The insured item a damage entry refers to, matched by item type. */
232	const damagedItem = (damage: Damage, items: Item[]): Item =>
233	  items.find((item) => item.type === damage.itemType) as Item;
234	
235	const incidentPayout = (incident: Incident, items: Item[]): number =>
236	  roundDown(
237	    incident.damages.reduce(
238	      (total, damage) => total + damagePayout(damage, damagedItem(damage, items)),
239	      0,
240	    ),
241	  );
242	
243	/** The payout is limited to what remains of the policy's cap. */
244	const claimResult = (
245	  incident: Incident,
246	  policy: QuoteStep,
247	  remainingCap: number,
248	): ClaimResult => {
249	  const payout = Math.min(incidentPayout(incident, policy.items), remainingCap);
250	
251	  return { payout, remainingCap: remainingCap - payout };
252	};
253	
254	/**
255	 * A scenario is walked step by step, because a claim draws on what earlier
256	 * claims left of its policy's cap. The caps of the policies quoted so far are
257	 * the only state carried from one step to the next.
258	 */
259	type RemainingCaps = Map<number, number>;
260	
261	const quoteStepResult = (
262	  step: QuoteStep,
263	  index: number,
264	  scenario: Scenario,
265	  remainingCaps: RemainingCaps,
266	): QuoteResult => {
267	  remainingCaps.set(index, policyCap(step));
268	
269	  return {
270	    premium: quotePremium(
271	      step,
272	      scenario.customer,
273	      isFollowUpContract(scenario.steps.slice(0, index)),
274	    ),
275	  };
276	};
277	
278	const claimStepResult = (
279	  step: ClaimStep,
280	  scenario: Scenario,
281	  remainingCaps: RemainingCaps,
282	): ClaimResult => {
283	  const policy = scenario.steps[step.policy] as QuoteStep;
284	  const result = claimResult(
285	    step.incident,
286	    policy,
287	    remainingCaps.get(step.policy) as number,
288	  );
289	
290	  remainingCaps.set(step.policy, result.remainingCap);
291	
292	  return result;
293	};
294	
295	export const runScenario = (scenario: Scenario): ScenarioResults => {
296	  const remainingCaps: RemainingCaps = new Map();
297	
298	  return {
299	    results: scenario.steps.map((step, index) =>
300	      step.op === "quote"
301	        ? quoteStepResult(step, index, scenario, remainingCaps)
302	        : claimStepResult(step, scenario, remainingCaps),
303	    ),
304	  };
305	};
